CustomField.formula:
/* =Champ de référence pour le naming ShareClass (logique métier). Toute évolution doit être répliquée dans l'apex ShareClassHandler (Product Catalog) pour éviter des incohérences sur les règles de nommage */ IF( ProjectProduct__r.RecordType.DeveloperName != "FundShareClassModification", IF( LegalForm__c = "OEIC",
/* ================= OEIC CASE ================= */
IF( TEXT(DividendPolicy__c) = "Accumulating",
/* ---- OEIC + ACCUMULATING ---- */ IF( ISBLANK(ProjectProduct__r.ProductName__c), ProjectProduct__r.Product__r.ProductName__c & " ", ProjectProduct__r.ProductName__c & " " ) & IF(ISBLANK(TEXT(Type__c)), "", TEXT(Type__c) & " ") & IF(ISBLANK(TEXT(Currency__c)), "", TEXT(Currency__c) & " ") & IF( TEXT(CurrencyHedging__c) = "True", "Acc Hdg", "Acc" ),
IF( TEXT(DividendPolicy__c) = "Income",
/* ---- OEIC + Income ---- */ IF( ISBLANK(ProjectProduct__r.ProductName__c), ProjectProduct__r.Product__r.ProductName__c & " ", ProjectProduct__r.ProductName__c & " " ) & IF(ISBLANK(TEXT(Type__c)), "", TEXT(Type__c) & " ") & IF(ISBLANK(TEXT(Currency__c)), "", TEXT(Currency__c) & " ") & IF( TEXT(CurrencyHedging__c) = "True", "Inc Hdg", "Inc" ),
/* ---- If other Dividend Policy under OEIC ---- */ NULL ) ),
/* ================= ORIGINAL LOGIC (NON-OEIC) ================= */
IF( ISBLANK(ProjectProduct__r.ProductName__c), ProjectProduct__r.Product__r.ProductName__c & " ", ProjectProduct__r.ProductName__c & " " ) &
IF(ISBLANK(TEXT(Type__c)), "", TEXT(Type__c) & " ") &
IF( TEXT(Type__c) = "MyInvestor", "", IF(ISBLANK(TEXT(Currency__c)), "", TEXT(Currency__c) & " ") &
IF( TEXT(DividendPolicy__c) = "Accumulating", "Acc ", IF( TEXT(DividendPolicy__c) = "Distributing", CASE( TEXT(DividendFrequency__c), "Monthly", "Mdis ", "Quarterly", "Qdis ", "Semi-Annually", "Sdis ", "Annually", "Ydis ", "Weekly", "Wdis ", "Daily", "Ddis ", "" ), IF( TEXT(DividendPolicy__c) = "Income", CASE( TEXT(DividendFrequency__c), "Monthly", "Minc ", "Quarterly", "Qinc ", "Semi-Annually", "Sinc ", "Annually", "Yinc ", "Weekly", "Winc ", "Daily", "Dinc ", "inc " ), "" ) ) ) &
IF(TEXT(CurrencyHedging__c) = "True", "Hdg", "") ) ), ShareClassNamePreModif__c )
